/**
 * Validates every team template in templates/*.yaml and writes src/generated.ts.
 * Run with --check in CI to fail when the generated file is out of date.
 *
 * Templates stay in YAML so anyone can contribute a team without writing code,
 * and the app imports plain data, so it works in any bundler or runtime.
 */
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { parse } from "yaml";
import { TeamTemplateSchema } from "../src/schema.ts";

const root = join(import.meta.dirname, "..");
const templatesDir = join(root, "templates");
const outFile = join(root, "src", "generated.ts");

const files = readdirSync(templatesDir)
  .filter((f) => f.endsWith(".yaml"))
  .sort();

const templates = files.map((file) => {
  const result = TeamTemplateSchema.safeParse(
    parse(readFileSync(join(templatesDir, file), "utf8")),
  );
  if (!result.success) {
    console.error(`✗ templates/${file}`);
    for (const issue of result.error.issues) {
      console.error(`  ${issue.path.join(".") || "(root)"}: ${issue.message}`);
    }
    process.exit(1);
  }
  if (`${result.data.id}.yaml` !== file) {
    console.error(`✗ templates/${file}: file name must match id "${result.data.id}"`);
    process.exit(1);
  }
  return result.data;
});

const output = `// Generated by \`pnpm catalog:generate\` from templates/*.yaml. Do not edit.
import type { TeamTemplate } from "./schema.ts";

export const TEAM_TEMPLATES: TeamTemplate[] = ${JSON.stringify(templates, null, 2)};
`;

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(outFile, "utf8");
  } catch {}
  if (current.replace(/\r\n/g, "\n") !== output) {
    console.error("✗ src/generated.ts is out of date. Run `pnpm catalog:generate`.");
    process.exit(1);
  }
  console.log(`✓ ${templates.length} team templates are valid and up to date.`);
} else {
  writeFileSync(outFile, output);
  console.log(`✓ Wrote ${templates.length} team templates to src/generated.ts.`);
}
